public class Main {
    static int 查了几项 = 0;
    static int 红了几项 = 0;

    static void 查相等(String 名字, int 叼回来, int 该是) {
        查了几项++;
        if (叼回来 == 该是) {
            System.out.println("绿 " + 名字);
        } else {
            红了几项++;
            System.out.println("红 " + 名字 + "：叼回来 " + 叼回来 + "，该是 " + 该是);
        }
    }

    public static void main(String[] args) {
        查相等("{l1}", 6 / 2, 3);
        查相等("{l2}", 8 / 2, 3);
        查相等("{l3}", 0 / 3, 0);
        System.out.println("体检了 " + 查了几项 + " 项，红了 " + 红了几项 + " 项");
    }
}
